#define GS_ENABLE 0
#define GS_SET_BC_CB 2
#define GS_BROADCAST 5

struct gs_cb {
    unsigned long flags;
    void *start_addr;
    // ...
};

// Enable guarded storage globally
long rc_enable = s390_guarded_storage(GS_ENABLE, NULL);

// Set a Control Block for a guarded region
struct gs_cb control_block = { .start_addr = 0x4000 };
long rc_set = s390_guarded_storage(GS_SET_BC_CB, &control_block);

// Trigger broadcast event
long rc_bcast = s390_guarded_storage(GS_BROADCAST, NULL);
